import React from 'react';
import { Truck, Navigation, CheckCircle } from 'lucide-react';

const ScheduleTab = () => {
  const tasks = [
    { id: 'T1', time: '08:00', loc: 'SECTOR_04', type: 'PICKUP', status: 'current' },
    { id: 'T2', time: '10:30', loc: 'ZONE_C', type: 'REPORT_FIX', status: 'pending' },
    { id: 'T3', time: '13:00', loc: 'PLAZA_SQ', type: 'PICKUP', status: 'pending' }
  ];

  return (
    <div className="w-full max-w-lg animate-slide-up space-y-6">
      <div className="flex justify-between items-end mb-4 px-4">
        <h3 className="text-4xl font-black italic text-[#47510B] uppercase tracking-tighter">Logistics<span className="text-[#CAD23C]">.</span></h3>
        <span className="text-[10px] font-black opacity-30 uppercase tracking-widest">Shift_08h</span>
      </div>

      <div className="space-y-4">
        {tasks.map((task) => (
          <div key={task.id} className={`group relative p-6 rounded-[40px] border-4 border-[#47510B] shadow-[8px_8px_0_0_#47510B] transition-all ${task.status === 'current' ? 'bg-[#CAD23C]' : 'bg-white hover:bg-[#FDFAD8]'}`}>
            <div className="flex justify-between items-start">
              <div>
                <span className="text-[10px] font-black opacity-40 italic">{task.time} // {task.id}</span>
                <h4 className="text-2xl font-black text-[#47510B] uppercase italic leading-none mt-1">{task.loc}</h4>
                <p className="text-[10px] font-black mt-2 opacity-60 tracking-[0.2em]">{task.type}</p>
              </div>

              <button 
                onClick={() => alert(`Opening Route for ${task.loc}...`)}
                className="w-14 h-14 bg-[#47510B] text-[#CAD23C] rounded-2xl flex items-center justify-center group-hover:rotate-12 transition-transform shadow-lg"
              >
                <Navigation size={28} strokeWidth={3} />
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default ScheduleTab;
